tests:
test({ sr: 'broji samoglasnike', en: 'counts vowels' }, () => {
  expect(countVowels('hello')).toBe(2);
});
test({ sr: 'velika slova se računaju', en: 'capital letters count' }, () => {
  expect(countVowels('HELLO')).toBe(2);
});
test({ sr: 'reč bez samoglasnika daje 0', en: 'a word without vowels gives 0' }, () => {
  expect(countVowels('rhythm')).toBe(0);
});
test({ sr: 'prazan tekst daje 0', en: 'empty text gives 0' }, () => {
  expect(countVowels('')).toBe(0);
});

hiddenTests:
test('every vowel in both cases', () => {
  expect(countVowels('AEIOU aeiou')).toBe(10);
});
test('only consonants and symbols', () => {
  expect(countVowels('xyz 123 !?')).toBe(0);
});
test('a repeated vowel counts each time', () => {
  expect(countVowels('aaaa')).toBe(4);
});

solutions.code:
function countVowels(text) {
  let count = 0;
  for (const char of text.toLowerCase()) {
    if ('aeiou'.includes(char)) count++;
  }
  return count;
}
